#!/usr/bin/env bash
# Copyright © 2026 Christopher Snow.
# Uses a built GPGPU-Sim checkout; no physical GPU or driver is needed.
set -eo pipefail
course_root=$(cd "$(dirname "$0")/.." && pwd)
sim_root=${GPGPUSIM_ROOT:-"$course_root/vendor/gpgpu-sim"}
sim_root=$(cd "$sim_root" && pwd)
output_root="$course_root/test-results/cuda-sim"
mkdir -p "$output_root"
cd "$sim_root"
# Generated by the CMake build; upstream's own CUDA sample job sources this.
source setup > "$output_root/setup.log" 2>&1
set -u

nvcc -O2 --cudart shared -gencode arch=compute_70,code=compute_70 \
  "$course_root/examples/gather.cu" -o "$output_root/gather"
{
  git -C "$sim_root" rev-parse HEAD
  nvcc --version
  ldd "$output_root/gather"
} > "$output_root/provenance.txt"
# Confirm that runtime calls are routed to the simulator, not the CUDA stub.
ldd "$output_root/gather" | grep 'libcudart.*gpgpu-sim'

for case_name in contiguous column misaligned tail multiblock; do
  case "$case_name" in
    contiguous) args=(1 0 32) ;;
    column) args=(8 0 32) ;;
    misaligned) args=(1 1 32) ;;
    tail) args=(1 1 8) ;;
    multiblock) args=(2 3 257) ;;
  esac
  run_dir="$output_root/$case_name"
  mkdir -p "$run_dir"
  cp "$sim_root"/configs/tested-cfgs/SM7_QV100/* "$run_dir/"
  (
    cd "$run_dir"
    PTX_SIM_MODE_FUNC=1 timeout 180 "$output_root/gather" "${args[@]}" > run.log 2>&1
  ) || { cat "$run_dir/run.log"; exit 1; }
  grep -q 'GPGPU-Sim' "$run_dir/run.log"
  grep -q "Verified ${args[2]} output values" "$run_dir/run.log"
  printf 'PASS: %s (stride %s, offset %s, n %s)\n' "$case_name" "${args[@]}"
done
